/* formato-oficial.js — el formato del Centro Evaluador, en un solo lugar.

   Los documentos que el sitio genera y que entran al portafolio deben verse
   como los que la SEP ya aceptó: los tres logos arriba, el título, las tablas
   en gris con borde negro y el pie con los datos del Centro. Medido sobre el
   expediente aprobado de Humberto (pág. 23, "Plan de Evaluación") y contra el
   machote del propio Centro, "Plan de evaluación EC1375-2.docx".

   Es módulo compartido —y no una copia por página— porque el mismo encabezado
   vive en el Plan, el Autodiagnóstico, los cuatro Documentos de Sesión, la
   Encuesta y los acuses: una copia desincronizada entre ellos es justo el modo
   de falla a evitar (ya pasó con el sidebar). Además los logos pesan 165 KB en
   base64 y así viajan una vez.

   Unidades: milímetros (el default de jsPDF). Hoja carta/A4, 210 mm de ancho. */
(function (root) {
    'use strict';

    /* Los tres logos, tomados del propio expediente aprobado. x/y son la
       esquina superior izquierda y ancho el impreso, medidos ahí mismo. */
    var LOGOS = {
        conocer: { x: 31.3, y: 12.0, w: 32.3, h: 18.2, img: 'data:image/png;base64,' },
        cicfm: { x: 87.9, y: 9.0, w: 39.5, h: 18.9, img: 'data:image/png;base64,' },
        ice: { x: 155.4, y: 12.6, w: 29.6, h: 14.2, img: 'data:image/png;base64,' }
    };

    /* Pie de página del Centro (sus datos), como pide el formato oficial:
       "Al pie de página: Datos del CE o EI (Dirección, Teléfono, …)". */
    var PIE = 'CENTRO EVALUADOR CE1399-OC063-18 - COLEGIO ILUSTRE DE CIENCIAS FORENSES DE MÉXICO A.C. - BRASIL 306-2 COL. 27 DE SEPTIEMBRE, POZA RICA, VER. - 7821138710 - cicfm.ce@gmail.com';

    var GRIS = [208, 208, 208];      /* el gris de los encabezados del formato */
    var NEGRO = [0, 0, 0];
    var TOPE = 50;                   /* donde puede empezar el contenido */
    var PIE_Y = 285;

    /* Estilos de tabla del formato: cabecera gris con texto negro y
       cuadrícula negra fina. Se pasan tal cual a jspdf-autotable. */
    var CABEZA = { fillColor: GRIS, textColor: 0, fontStyle: 'bold', lineColor: NEGRO, lineWidth: 0.1, halign: 'center' };
    var CUADRICULA = { lineColor: NEGRO, lineWidth: 0.1 };
    /* Columna de etiquetas: gris, negrita y alineada a la derecha, como en el
       encabezado del Plan aprobado ("Evaluadora:", "Centro de Evaluación:"). */
    var ETIQUETA = { fillColor: GRIS, textColor: 0, fontStyle: 'bold', halign: 'right' };
    /* Fila que abre un bloque a todo lo ancho (los "ELEMENTO 1" del Plan). */
    function banda(texto, colSpan, size) {
        return { content: texto, colSpan: colSpan, styles: { fillColor: GRIS, textColor: 0, fontStyle: 'bold', halign: 'center', fontSize: size || 8.5 } };
    }

    function logo(doc, l) { doc.addImage(l.img, 'PNG', l.x, l.y, l.w, l.h); }

    /* Encabezado y pie de UNA hoja. Devuelve la y donde empieza el contenido.
       El título se repite en cada hoja porque en el formato del Centro vive en
       el encabezado de Word, no solo en la primera. */
    function hoja(doc, titulo) {
        logo(doc, LOGOS.conocer); logo(doc, LOGOS.cicfm); logo(doc, LOGOS.ice);
        if (titulo) {
            var antes = doc.getFontSize();
            doc.setFontSize(14); doc.setFont(undefined, 'bold'); doc.setTextColor(0);
            doc.text(titulo, 105, 38, { align: 'center' });
            doc.setFontSize(antes); doc.setFont(undefined, 'normal');
        }
        pie(doc);
        return TOPE;
    }

    function pie(doc) {
        var antes = doc.getFontSize();
        doc.setFontSize(5.8); doc.setFont(undefined, 'bold'); doc.setTextColor(0);
        doc.text(doc.splitTextToSize(PIE, 180), 105, PIE_Y, { align: 'center' });
        doc.setFontSize(antes); doc.setFont(undefined, 'normal');
    }

    /* Pasa por todas las hojas ya creadas y les pone encabezado y pie. Se
       llama al final, cuando ya se sabe cuántas son. */
    function enCadaHoja(doc, titulo) {
        var n = doc.getNumberOfPages();
        for (var i = 1; i <= n; i++) { doc.setPage(i); hoja(doc, titulo); }
        doc.setPage(n);
    }

    var api = { LOGOS: LOGOS, PIE: PIE, GRIS: GRIS, TOPE: TOPE, PIE_Y: PIE_Y,
        CABEZA: CABEZA, CUADRICULA: CUADRICULA, ETIQUETA: ETIQUETA,
        banda: banda, hoja: hoja, pie: pie, enCadaHoja: enCadaHoja };
    if (typeof module !== 'undefined' && module.exports) module.exports = api;
    else root.FormatoOficial = api;
})(typeof window !== 'undefined' ? window : globalThis);
